std::vector<std::vector<Point>> faces;
std::vector<double> edge_lengths;
for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    if (it->second < threshold) {
        std::vector<Point> face;
        auto cell1 = it->first.first;
        auto cell2 = it->first.second;
        face.push_back(rt.triangle(cell1).vertex(0));
        face.push_back(rt.triangle(cell1).vertex(1));
        face.push_back(rt.triangle(cell1).vertex(2));
        face.push_back(rt.triangle(cell2).vertex(0));
        face.push_back(rt.triangle(cell2).vertex(1));
        face.push_back(rt.triangle(cell2).vertex(2));
        faces.push_back(face);
        edge_lengths.push_back(it->second);
    }
}
Mesh<Point, double> mesh;
mesh.faces = faces;
mesh.edge_lengths = edge_lengths;
return mesh;

